            {
                "name": "wind_chill_formula_and_gate",
                "points": 3,
                "description": "Gives WC = 13.12 + 0.6215*T - 11.37*V^0.16 + 0.3965*T*V^0.16, defines T in deg C and V in km/h, and applies T <= 10 C plus V > 4.8 km/h.",
                "partial_credit": "Award 2 points for the correct formula with missing gate or units, or 1 point for a recognizable power-law wind-chill equation with coefficient errors.",
            },
            {
                "name": "persistence_windows",
                "points": 4,
                "description": "Reports a three-day daily below-freezing run and about 60 consecutive below-freezing hours, with both compared to the thresholds.",
                "partial_credit": "Award 2-3 points for one exact run plus one incomplete or slightly imprecise run, or 1 point for only qualitative multi-day freezing.",
            },
            {
                "name": "temperature_vs_apparent_exposure",
                "points": 3,
                "description": "Separates measured air temperature from wind chill and reports about -6.3 C, -17.1 C, and 10.8 C amplification.",
                "partial_credit": "Award 2 points for two of the three values, or 1 point for noting the distinction without the numeric separation.",
            },
            {
                "name": "cold_load_and_snow_ledger",
                "points": 3,
                "description": "Reports freezing degree-hours near 177.4 C-h, base-18 heating degree-days near 124.2 C-days, and snowfall near 9.87 cm.",
                "partial_credit": "Award 2 points for two correct anchors, or 1 point for one correct anchor with the right unit concept.",
            },
            {
                "name": "threshold_rejection_logic",
                "points": 3,
                "description": "Rejects the brief-anomaly, wind-chill-only, and snow/ice-primary labels using the stated inequalities.",
                "partial_credit": "Award 2 points for two correct rejections, or 1 point for one correct rejection.",
            },
            {
                "name": "concise_computed_interpretation",
                "points": 1,
                "description": "Gives one event-specific sentence tied to the ledger and avoids casualty, loss, livestock, spatial-field, or formal attribution escalation.",
                "partial_credit": "Award 0.5 point for a mostly concise sentence with minor overreach.",
            },
        ],
    }


def compute() -> dict[str, Any]:
    metrics = compute_metrics()
    answer, threshold_tests = classify(metrics)
    primary_gt = {
        "target_family": TARGET_FAMILY,
        "answer": answer,
        "ledger": metrics,
        "threshold_tests": threshold_tests,
        "decision_rule": "label sustained_freezing_cold when daily run >= 3 days and hourly freezing run >= 48 hours",
        "tolerances": {
            "temperature_c": 0.3,
            "run_hours": 1,
            "degree_hours": 1.0,
            "snow_cm": 0.1,
        },
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "key_values": {
            "answer": answer,
            **metrics,
            **threshold_tests,
        },
        "formulae": {
            "wind_chill_c": "WC = 13.12 + 0.6215*T - 11.37*V^0.16 + 0.3965*T*V^0.16",
            "wind_chill_gate": "T <= 10 C and V > 4.8 km/h",
            "freezing_degree_hours_c_h": "sum(max(0, 0 - hourly_T_c))",
            "heating_degree_days_base18c": "sum(max(0, 18 - hourly_T_c)) / 24",
        },
        "numeric_tolerances": {
            "min_tmin_c": {"target": -6.3, "tolerance": 0.2, "unit": "deg C"},
            "daily_below_freezing_run_days": {"target": 3, "tolerance": 0, "unit": "days"},
            "freezing_run_hours": {"target": 60, "tolerance": 1, "unit": "hours"},
            "min_wind_chill_c": {"target": -17.1, "tolerance": 0.3, "unit": "deg C"},
            "wind_chill_amplification_c": {"target": 10.8, "tolerance": 0.3, "unit": "deg C"},
            "freezing_degree_hours_c_h": {"target": 177.4, "tolerance": 1.0, "unit": "deg C hours"},
            "heating_degree_days_base18c": {"target": 124.2, "tolerance": 0.5, "unit": "deg C days"},
            "event_snowfall_cm": {"target": 9.87, "tolerance": 0.1, "unit": "cm"},
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "data_source": PACKAGE_RELATIVE_PATH,
            "source_files": [
                "data/physical_hazard/physical_hazard_001_Open-Meteo_historical_archive_cold_variables.json"
            ],
        },
        "rubric": rubric(),
    }


def main() -> None:
    output_path = task_dir() / "computed_gt.json"
    result = compute()
    apply_deepened_task_frame(result)
    output_path.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
